def check(output: str, ctx: dict) -> bool:
    question = ctx['question'].lower()
    sql = extract_sql(output).lower()
    mentioned_columns = [col.lower() for table, cols in ctx['schema'].items() for col in cols if col.lower() in question]
    try:
        if 'select' in sql:
            select_columns = sql.split('from')[0].replace('select', '').split(',')
            select_columns = [col.strip().split()[-1] for col in select_columns]
            return all(any(mc in col for col in select_columns) for mc in mentioned_columns)
        return True
    except:
        return True

def check(output: str, ctx: dict) -> bool:
