def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    table_mentions = [table for table in ctx['schema'] if table.lower() in sql]
    if len(table_mentions) > 1:
        return ' as ' in sql or any(f'{table.lower()}.' in sql for table in table_mentions)
    return True

