def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    if len(ctx['schema']) > 1:
        columns = re.findall(r'\b[a-z_]+\b', sql.split('from')[0])
        return all('.' in col for col in columns)
    return True

def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    tables = [table.lower() for table in ctx['schema']]
    if any(sql.count(table) > 1 for table in tables):
        return ' as ' in sql
    return True

def check(output: str, ctx: dict) -> bool:
    question = ctx['question'].lower()
    sql = extract_sql(output).lower()
    literals = re.findall(r'".*?"|\'.*?\'|\b\d+\b', question)
    return all(literal in sql for literal in literals)

def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    try:
        select_clause = sql.split('from')[0].replace('select', '').strip()
        selected_columns = [col.strip() for col in select_clause.split(',')]
        return len(selected_columns) == len(set(selected_columns))
    except:
        return True

def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    try:
        select_clause = sql.split('from')[0].replace('select', '').strip()
        group_by_clause = sql.split('group by')[1].split('order by')[0] if 'group by' in sql else ''
        selected_columns = [col.strip().split()[-1] for col in select_clause.split(',') if not any(func in col for func in ['count(', 'avg(', 'sum(', 'max(', 'min('])]
        grouped_columns = [col.strip() for col in group_by_clause.split(',')]
        return all(col in grouped_columns for col in selected_columns)
    except:
        return True

def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    if 'where' in sql:
        where_conditions = sql.split('where')[1].split('group by')[0].split('order by')[0]
        return 'and' in where_conditions or 'or' in where_conditions
    return True

def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    schema_tables = {table.lower() for table in ctx['schema']}
    try:
        from_clause = sql.split('from')[1].split('where')[0].split('group by')[0].split('order by')[0]
        referenced_tables = re.findall(r'\b[a-z_]+\b', from_clause)
        return all(table in schema_tables for table in referenced_tables)
    except:
        return True

def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    schema_columns = {col.lower() for table_cols in ctx['schema'].values() for col in table_cols}
    aggregates = re.findall(r'(count|avg|sum|max|min)\((.*?)\)', sql)
    return all(col.strip() in schema_columns or col.strip() == '*' for _, col in aggregates)
